
const conversationId=localStorage.getItem('jarvis-conversation-id')||crypto.randomUUID().replaceAll('-','');localStorage.setItem('jarvis-conversation-id',conversationId);
function chatActions(row,answer){
const detail=answer?.data;
if(answer?.route==='LOCAL_SCENARIO'&&detail){const values=document.createElement('pre');values.textContent=scenarioExplanation(detail);row.append(values)}
const revisions=(answer?.source_revisions||[]).filter(s=>typeof s==='string'&&/^[0-9a-f]{64}$/.test(s));
if(revisions.length){const source=document.createElement('p');source.textContent='Идентификаторы расчёта / источников: '+revisions.join(' · ');row.append(source)}
if(detail?.snapshot_accepted&&detail.source_sha256){const source=document.createElement('p');source.textContent='Snapshot '+detail.source_sha256+'; audit revision '+detail.audit_revision+'; версия '+detail.snapshot_version+'; валюта '+detail.currency;row.append(source)}
function action(label,run){const button=document.createElement('button');button.textContent=label;button.onclick=async()=>{try{await run()}catch(e){const error=document.createElement('p');error.textContent=e.message;row.append(error)}};row.append(button)}
if(answer?.route==='LOCAL_REVIEW')action('Открыть pending review',async()=>{document.getElementById('status').value='pending_review';offset=0;await load();navigate('operations')});
for(const id of (answer?.review_ids||[]).slice(0,5))if(typeof id==='string'&&/^[0-9a-f]{24}$/.test(id))action('Открыть событие '+id.slice(0,8),()=>show(id));
if(answer?.route==='LOCAL_FINANCE'&&detail?.scope==='accepted_statements_only'){action('Открыть принятые выписки',()=>{navigate('sources');loadStatements()});if(detail.period)action('Покниколайь движение выбранного периода',()=>{document.getElementById('statement-start').value=detail.period[0];document.getElementById('statement-end').value=detail.period[1];document.getElementById('statement-currency').value=detail.currency;navigate('analytics');document.getElementById('statement-report').click()});for(const operation of (detail.category_operations||[]).slice(0,5))action('Открыть категорию '+operation.date,()=>show(operation.review_id));}
if(answer?.route==='LOCAL_MEMORY')action('Открыть память и историю решений',()=>{navigate('learning');document.getElementById('memory').click()});
if(answer?.route==='LOCAL_SOURCE_STATUS')action('Открыть доступность источников',()=>{document.getElementById('availability').click();navigate('sources')});
if(answer?.route==='LOCAL_SCENARIO'&&detail)action(detail.scope==='HYPOTHETICAL'?'Изменить параметры расчёта':'Открыть панель принятых сценариев',()=>navigate('analytics'));
if(answer?.route==='LOCAL_FINANCE'&&detail?.scope!=='accepted_statements_only'&&detail?.period&&/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(detail.period[0])&&/^[A-Z]{3}$/.test(detail.currency)){
action('Пересчитать и покниколайь финансовые детали',()=>{document.getElementById('question-month').value=detail.period[0].slice(0,7);document.getElementById('question-currency').value=detail.currency;document.getElementById('question-intent').value=['spending','expense_history','category_growth','recurring','duplicates','missing_data','stale_balances','available_funds'].includes(detail.intent)?detail.intent:'missing_data';document.getElementById('question-text').value='';document.getElementById('question').click();navigate('analytics')})}
}
function renderChat(message,answer){const row=document.createElement('article');const q=document.createElement('p');q.textContent=message;const a=document.createElement('p');a.textContent=answer?.text||'Незавершённый или истёкший запрос. Автоповтора нет.';const meta=document.createElement('small');meta.textContent=[answer?.route,answer?.status,answer?.nl_parameters&&answer?.status==='insufficient_data'&&!answer?.historical?'нужно уточнение':answer?.current?'текущий':'исторический / неактуальный','стоимость: '+(answer?.cost_rub??'неизвестно')+' RUB',answer?.simulation?'MOCK, не реальные расходы':'',...(answer?.limitations||[])].filter(Boolean).join(' · ');row.append(q,a,meta);for(const citation of answer?.citations||[]){const c=document.createElement('p');c.textContent='Источник '+(citation.source_sha256||'')+'; страница '+citation.page;row.append(c)}chatActions(row,answer);document.getElementById('chat-turns').append(row)}
document.getElementById('chat-send').onclick=async()=>{const button=document.getElementById('chat-send');if(button.disabled)return;button.disabled=true;document.getElementById('chat-state').textContent='Проверяю источники…';try{const message=document.getElementById('chat-input').value;const body={message,conversation_id:conversationId,request_id:crypto.randomUUID().replaceAll('-',''),public_cloud:document.getElementById('chat-cloud').checked,explain:document.getElementById('chat-explain').checked};const month=document.getElementById('chat-month').value;if(month)body.month=month;const answer=await api('/api/chat','POST',body);renderChat(message,answer);document.getElementById('chat-input').value=''}catch(e){renderChat('',{text:e.message,status:'unavailable',current:false})}finally{button.disabled=false;document.getElementById('chat-state').textContent='Готово'}};
document.getElementById('chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!document.getElementById('chat-send').disabled)document.getElementById('chat-send').click()}};
document.getElementById('goal-chat').onclick=async()=>{const button=document.getElementById('goal-chat');if(button.disabled)return;button.disabled=true;document.getElementById('chat-state').textContent='Рассчитываю гипотетический сценарий локально…';try{
const scenario={mode:'hypothetical_goal',target:document.getElementById('goal-target').value,starting:document.getElementById('goal-starting').value,monthly_contribution:document.getElementById('goal-monthly').value,currency:document.getElementById('goal-currency').value,start:document.getElementById('goal-start').value,months:Number(document.getElementById('goal-months').value),contribution_delay_months:Number(document.getElementById('goal-delay').value)};
if(document.getElementById('goal-deadline').value)scenario.deadline=document.getElementById('goal-deadline').value;
const message='Гипотетический сценарий накоплений';const answer=await api('/api/chat','POST',{message,conversation_id:conversationId,request_id:crypto.randomUUID().replaceAll('-',''),public_cloud:false,scenario});renderChat(message,answer);navigate('assistant');
}catch(e){renderChat('',{text:e.message,status:'unavailable',current:false})}finally{button.disabled=false;document.getElementById('chat-state').textContent='Готово; сценарий не сохранён как финансовая цель'}};
document.getElementById('chat-history').onclick=async()=>{try{const d=await api('/api/chat/'+conversationId);document.getElementById('chat-turns').textContent='';for(const t of d.turns)renderChat(t.message||'Содержимое удалено по сроку хранения',t.answer)}catch(e){renderChat('',{text:e.message,status:'unavailable',current:false})}};
const token=TOKEN;let selected=null,offset=0;const $=id=>document.getElementById(id);
$('ai-status').onclick=async()=>{try{const d=await api('/api/ai/status');$('ai-data').textContent='Режим: '+d.mode+'; модель: '+d.model+'; журнал: '+d.status+'; '+(d.simulation?'симуляция, не реальные расходы':'реальные расходы / резервы')+'\nЗанято сегодня: '+(d.committed_today??'недоступно')+' RUB; за месяц: '+(d.committed_month??'недоступно')+' RUB\nОстаток сегодня: '+(d.remaining_daily??'недоступно')+' RUB; за месяц: '+(d.remaining_monthly??'недоступно')+' RUB\nЗапросов: '+(d.requests??'неизвестно')+'; неизвестных списаний: '+(d.uncertain??'неизвестно')+'; решено локально в этом процессе: '+d.local_questions+'\nПоследняя ошибка: '+(d.source_error??'не наблюдалась в этом процессе');}catch(e){$('ai-data').textContent=e.message}};
$('ai-disable').onclick=async()=>{try{await api('/api/ai/disable','POST',{});$('ai-status').click();}catch(e){$('ai-data').textContent=e.message}};
$('ai-owner-activate').onclick=async()=>{const button=$('ai-owner-activate');button.disabled=true;try{
if(!$('ai-owner-confirm').checked)throw Error('Требуется отдельное локальное согласие владельца');
const policy={purpose:'public_development',mode:'live',fields:[],model:'qwen3.7-flash',expires_at:new Date(Date.now()+Number($('ai-owner-hours').value)*3600000).toISOString(),maximum_requests:Number($('ai-owner-max').value),request_budget_rub:'0.03',daily_budget_rub:'1',monthly_budget_rub:'10'};
let action=JSON.parse(localStorage.getItem('jarvis-developer-activation')||'null');if(!action){action={policy,actor:$('ai-owner').value,confirmed:true,action_id:crypto.randomUUID().replaceAll('-','')};localStorage.setItem('jarvis-developer-activation',JSON.stringify(action))}const d=await api('/api/ai/activate',action);
localStorage.setItem('jarvis-developer-permission',d.permission_id);$('ai-data').textContent=JSON.stringify(d,null,2);
}catch(e){$('ai-data').textContent=e.message}finally{$('ai-owner-confirm').checked=false;button.disabled=false}};
$('ai-owner-revoke').onclick=async()=>{try{const permission_id=localStorage.getItem('jarvis-developer-permission');if(!permission_id)throw Error('В этом браузере нет разрешения разработки');await api('/api/teacher/revoke',{permission_id,actor:$('ai-owner').value});localStorage.removeItem('jarvis-developer-permission');localStorage.removeItem('jarvis-developer-activation');$('ai-data').textContent='Разрешение отозвано. История расходов и UNKNOWN сохранены.'}catch(e){$('ai-data').textContent=e.message}};
$('ai-key-check').onclick=async()=>{try{$('ai-data').textContent=JSON.stringify(await api('/api/ai/owner-key-check','POST',{}),null,2)}catch(e){$('ai-data').textContent=e.message}};
$('ai-history').onclick=async()=>{try{const d=await api('/api/ai/status');$('ai-history-data').textContent=JSON.stringify({status:d.status,simulation:d.simulation,settled_today:d.settled_today??null,settled_month:d.settled_month??null,unresolved_reserves:d.unresolved_reserves??null,daily_limit:d.daily_limit_rub??null,monthly_limit:d.monthly_limit_rub??null,requests_today:d.requests_today??null,requests_month:d.requests_month??null,by_model:d.requests_by_model??null,daily_counters:d.daily_counters??null,monthly_counters:d.monthly_counters??null,reasoning_tokens:d.reasoning_tokens??null,provider_cached_tokens:d.provider_cached_tokens??null,tariff_history:d.tariff_history??null,provider_errors:d.provider_errors??null},null,2)}catch(e){$('ai-history-data').textContent=e.message}};
$('knowledge-answer').onclick=async()=>{try{const d=await api('/api/knowledge-question','POST',{question:$('knowledge-question').value});$('knowledge-data').textContent=JSON.stringify(d,null,2);$('ai-status').click();}catch(e){$('knowledge-data').textContent=e.message}};
$('memory').onclick=async()=>{try{const d=await api('/api/memory');const lines=['Подтверждение категории не принимает финансовый источник'];$('memory-notes').replaceChildren();
for(const f of d.facts)lines.push('Операция: '+f.item_id+'; категория: '+f.category+'; подтверждено '+f.confirmed_at+'; policy '+f.policy_version+'; source SHA: '+f.source_sha256);
for(const h of d.category_history)lines.push('История: '+h.timestamp+'; операция '+h.item_id+'; '+h.action+'; категория '+(h.category??'не назначена')+'; revision '+h.seq+'; source SHA: '+h.source_sha256);
for(const kind of ['preferences','hypotheses','predictions'])for(const n of d[kind]){lines.push((kind==='preferences'?'Предпочтение':kind==='hypotheses'?'Гипотеза':'Прогноз')+': '+n.text+' ['+({nonfinancial_note:'нефинансовая заметка',expired:'срок истёк',revoked:'отозвано'}[n.status]||'неизвестное состояние')+']');
if(n.status!=='revoked'){const button=document.createElement('button');button.textContent='Отозвать заметку: '+n.text.slice(0,60);button.onclick=async()=>{try{await api('/api/memory-notes/'+n.id+'/revoke','POST',{actor:$('actor').value,expected_revision:n.revision});$('memory').click();}catch(e){$('memory-data').textContent=e.message}};$('memory-notes').append(button);}}
lines.push('Исторических событий категорий: '+d.category_history.length+'; гипотезы и прогнозы не являются labels');$('memory-data').textContent=lines.join('\n');}catch(e){$('memory-data').textContent=e.message}};
$('note-save').onclick=async()=>{try{await api('/api/memory-notes','POST',{kind:$('note-kind').value,text:$('note-text').value,actor:$('actor').value});$('note-text').value='';$('memory').click();}catch(e){$('memory-data').textContent=e.message}};
$('question').onclick=async()=>{try{const d=await api('/api/financial-question','POST',{intent:$('question-intent').value,month:$('question-month').value,currency:$('question-currency').value,question:$('question-text').value.trim()||null});
$('category-chart').replaceChildren();
const lines=[d.status==='available'?'Расчёт по явно принятой области источников':'Достоверный итог недоступен: неполные, устаревшие или непринятые данные'];
if(d.explanation)lines.push(d.explanation);if(d.reason)lines.push(d.reason);
if(d.source_sha256)lines.push('Snapshot SHA-256: '+d.source_sha256+'; audit revision: '+d.audit_revision+'; версия: '+d.snapshot_version);
if(typeof d.answer==='string')lines.push('Сумма: '+d.answer+' '+d.currency);
else if(Array.isArray(d.answer))for(const row of d.answer)lines.push(row.category?row.category+': '+row.previous+' → '+row.current+'; изменение '+row.change:'Повторяющийся расход: '+row.amount_total+' '+d.currency+'; требует подтверждения');
else if(d.answer){if(d.intent==='missing_data')lines.push('Неполных счетов: '+d.answer.incomplete_accounts.length+'; неизвестных остатков: '+d.answer.unknown_balances.length+'; pending: '+d.answer.pending_source_events);
if(d.intent==='expense_history'){for(const r of d.answer.operations)lines.push(r.date+'; операция '+r.transaction_id+'; '+r.signed_amount+' '+r.currency+'; '+r.category+'; расходы с возвратами: '+r.net_expense);
for(const r of d.answer.by_category){const label=document.createElement('label');label.textContent=r.category+': '+r.net_expense+' '+d.currency;const meter=document.createElement('meter');meter.min=0;meter.max=Number(d.answer.chart_max);meter.value=Math.max(0,Number(r.net_expense));label.append(meter);$('category-chart').append(label);}}
if(d.intent==='duplicates')lines.push('Групп совпадающих ID: '+d.answer.observed_duplicate_groups.length+'; автоматическое объединение запрещено');
if(d.intent==='stale_balances')lines.push('Исторический остаток на '+d.answer.asof+' не подтверждает текущие доступные средства');}
if(d.intent==='available_funds')lines.push('Нужны отдельно принятые текущие остатки, резерв и обязательства: используйте capacity preview');
if(d.status==='available'&&d.period_comparison){const c=d.period_comparison;lines.push('Сравнение всех категорий: '+c.previous_days+' → '+c.current_days+' дней; '+c.units+'; изменение не доказывает причину');
for(const r of c.categories)lines.push(r.category+': '+r.previous+' → '+r.current+' '+c.currency+'; в день '+r.previous_daily+' → '+r.current_daily+'; изменение в день '+r.daily_change);}
if(d.period)lines.push('Период: '+d.period.join(' — ')+'; валюта: '+d.currency);lines.push('Подлинность банка этим расчётом не подтверждается; финансового применения нет');$('question-data').textContent=lines.join('\n');}
catch(e){$('question-data').textContent=e.message}};
$('pending-review').onclick=()=>{$('status').value='pending_review';offset=0;load();navigate('operations');};
let workbenchFacts={};
const workbenchLabels={inventory:'Состав ликвидных счетов',balances:'Остатки',obligations:'Обязательства',reserve:'Резерв',
total_assets:'Всего активов',liabilities:'Долги',goals_progress:'Прогресс целей',income:'Доходы',expenses:'Расходы',free_cash:'Свободные средства'};
const workbenchStates={available:'доступно',stale:'устарело',unavailable:'недоступно',revoked:'отозвано',corrupt:'повреждено',
parser_changed:'изменился парсер',source_changed:'изменился оригинал',evidence_mismatch:'расхождение докниколайельств',unknown:'неизвестно',
human_reviewed_source_claim:'принято отдельным решением',pending_review:'ожидает проверки',insufficient_data:'недостаточно данных',blocked:'заблокировано'};
$('workbench').onclick=async()=>{try{const d=await api('/api/workbench');workbenchFacts=d.capacity_input_selection?.fact_ids||{};
const rows=['Режим: '+(d.status==='read_only_review'?'только просмотр':'недоступно, обновите панель'),'Данные источников не подтверждают банковскую подлинность','Демонстрация: '+(d.synthetic_demonstration?'синтетическая':'происхождение всей выборки не подтверждено'),
'Событий: '+(d.review?.total??'неизвестно')+'; конфликтов: '+(d.review?.conflicts??'неизвестно')];
for(const [k,v] of Object.entries(d.sources?.sources||{}))rows.push('Источник '+k+': '+(workbenchStates[v.status]||v.status));
for(const [k,v] of Object.entries(d.facts||{}))rows.push((workbenchLabels[k]||k)+': '+(v.length?v.map(r=>(workbenchStates[r.status]||r.status)+(r.synthetic_demonstration?' [синтетические данные]':'')).join(', '):'неизвестно'));
for(const [k,v] of Object.entries(d.unknown||{}))rows.push((workbenchLabels[k]||k)+': '+(v===null?'не подтверждено':v));
if(d.observed_banking){const b=d.observed_banking;rows.push('Банковские наблюдения'+(b.synthetic?' [синтетические]':'')+'; полнота: '+b.coverage,
'Наблюдаемые RUB-счета, без добавления карт: '+(b.rub_account_subtotal??'неизвестно')+'; финансовый смысл не принят');
const h=b.history;if(h){rows.push('Обновление остатков: '+(h.balance_freshness.last_success??'неизвестно')+'; '+(workbenchStates[b.balance_availability]||b.balance_availability),
'Полная финансовая история не подтверждена'+(h.source_error?'; чтение завершилось ошибкой':''),
'Версия источника: '+(h.source_revision??'неизвестно')+'; парсер: '+(h.parser_version??'неизвестно')+'; audit revision: '+(h.audit_revision??'неизвестно'));
for(const r of h.resources)rows.push((r.kind==='accounts'?'История счёта ':'История карты ')+'••'+(r.last4??'????')+': '+
(r.status==='observed'?'прочитано страниц '+r.pages_read+', наблюдений '+r.observations:r.status==='not_read'?'не прочитана':'ресурс недоступен')+
'; периоды: '+(r.periods.length?r.periods.map(p=>p.start+' — '+p.end+(p.terminal===true?' (видимое окно завершено)':' (неполное/неизвестное окно)')).join(', '):'неизвестны')+
'; повторных наблюдений: '+(r.repeated_observations??'неизвестно')+'; конфликтных ID: '+(r.conflicting_native_ids??'неизвестно')+
'; review: '+JSON.stringify(r.review_states||{})+(r.inventory_presence==='historical_observation'?'; ресурс только в прежнем снимке':''));}
for(const kind of ['accounts','cards'])for(const p of (b[kind]||[]))rows.push((kind==='accounts'?'Счёт ':'Карта ')+(p.name??'тип неизвестен')+' ••'+(p.last4??'????')+': '+(p.balance?.amount??'неизвестно')+' '+(p.balance?.currency??'валюта неизвестна'))}
rows.push('Сценарий = принятые ликвидные остатки − резерв − обязательства периода − явно заданные расходы.',
'Четыре принятых факта дополнительно проверяются по валюте, периоду, свежести и полноте.',
'Будущий доход и курс обмена не предполагаются. Сценарий не разрешает финансовое действие.');$('workbench-data').textContent=rows.join('\n')}
catch(e){$('workbench-data').textContent=e.message}};
$('capacity-chat').onclick=async()=>{const button=$('capacity-chat');if(button.disabled)return;button.disabled=true;try{
if(Object.keys(workbenchFacts).length!==4)throw Error('Откройте workbench: нужны четыре отдельно принятых факта, конфликты не выбираются автоматически');
const scope={fact_ids:workbenchFacts,start:$('plan-start').value,end:$('plan-end').value,currency:$('plan-currency').value};
const preview=await api('/api/capacity-preview',{...scope,scenarios:{before_scenario_spending:'0'}});
if(!preview.accepted_evidence_sha256)throw Error(preview.reason||'Нет актуальных согласованных принятых источников');
const scenario={...scope,mode:'accepted_capacity',accepted_source_revision:preview.accepted_evidence_sha256};
if($('plan-base').value){scenario.base_spending=$('plan-base').value;scenario.expense_growth_percent=$('plan-growth').value}
const message='Сценарий по отдельно принятым источникам';renderChat(message,await api('/api/chat','POST',{message,conversation_id:conversationId,request_id:crypto.randomUUID().replaceAll('-',''),public_cloud:false,scenario}));
$('chat-turns').scrollIntoView();}catch(e){$('capacity-data').textContent=e.message}finally{button.disabled=false}};
$('capacity').onclick=async()=>{try{if(Object.keys(workbenchFacts).length!==4)throw Error('Нужны четыре отдельно принятых факта; конфликтные факты требуют ручного выбора');
if(!$('plan-base').value||!$('plan-stress').value)throw Error('Расходы сценариев необходимо укниколайь явно');
const d=await api('/api/capacity-preview',{fact_ids:workbenchFacts,start:$('plan-start').value,end:$('plan-end').value,
currency:$('plan-currency').value,scenarios:{base:$('plan-base').value,stress:$('plan-stress').value}});
if(!d.scenarios){$('capacity-data').textContent='Расчёт недоступен: '+(d.reason||'недостаточно принятых докниколайельств');return}
const lines=['Валюта: '+d.input_summary.currency,'Период: '+d.period.join(' — '),'Ликвидные остатки: '+d.input_summary.liquid_balance,
'Обязательства: '+d.input_summary.obligations,'Резерв: '+d.input_summary.reserve];
for(const [name,s] of Object.entries(d.scenarios))lines.push((name==='base'?'Базовый':'Стресс')+' сценарий: остаток после расходов '+s.headroom+'; дефицит '+s.shortfall);
lines.push('Это сценарий по отдельно принятым фактам. Финансовое действие запрещено.');$('capacity-data').textContent=lines.join('\n')}
catch(e){$('capacity-data').textContent=e.message}};
function downloadJson(d,name){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));
a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function api(path,bodyOrMethod,explicitBody){const body=typeof bodyOrMethod==='string'?explicitBody:bodyOrMethod;
const method=typeof bodyOrMethod==='string'?bodyOrMethod:body?'POST':'GET';if(!['GET','POST'].includes(method)||method==='GET'&&body!==undefined)throw Error('Неподдерживаемый запрос');
const r=await fetch(path,{method,headers:{'X-Review-Token':token,
'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json()}catch(e){throw Error('Источник недоступен: HTTP '+r.status)};
if(!r.ok)throw Error(d.detail||'Ошибка проверки');return d}
async function load(){try{const d=await api('/api/queue-search',{offset,classification:$('classification').value,reason:$('reason').value,status:$('status').value,
search:$('search').value,card:$('card-filter').value,start:$('date-start').value||null,end:$('date-end').value||null,direction:$('direction').value});
if(offset>0&&offset>=d.total){offset=Math.max(0,Math.floor((d.total-1)/50)*50);return load()}
$('previous').disabled=offset===0;$('next').disabled=offset+50>=d.total;
$('counts').textContent=d.total+' из '+d.progress.total+' событий; не проверено: '+(d.progress.statuses.pending_review||0)+
'; событий audit: '+d.decisions+'; подтверждённых категорий: '+d.progress.human_labels;$('list').replaceChildren();for(const x of d.items){
const b=document.createElement('button');b.className='row';const info=document.createElement('span');const title=document.createElement('strong');title.textContent=x.merchant||x.description||'Описание не предоставлено';const meta=document.createElement('small');meta.textContent=[x.date||'Нет даты',x.card?'••'+x.card.slice(-4):x.source_label||'Счёт не определён',x.label_decision?.action==='confirm'?'Категория подтверждена: '+categoryName(x.label_decision.category):'Категория требует проверки'].join(' · ');info.append(title,meta);const money=document.createElement('span');money.className='money';money.textContent=moneyText(x.amount,x.currency);b.append(info,money);
b.onclick=()=>show(x.id);$('list').append(b)}$('message').textContent=''}catch(e){$('message').textContent=e.message}}
async function show(id){try{selected=await api('/api/items/'+id);$('detail').hidden=false;renderOperation(selected);$('detail').scrollTop=0;$('evidence').textContent=JSON.stringify(selected,null,2);
$('candidate').replaceChildren(new Option('Выберите явно',''));for(const c of selected.candidates){
const d=c.db_operation;$('candidate').add(new Option(c.db_id+' · '+d.account+' · '+d.tx_date+' · '+d.amount,c.db_id))}
}catch(e){$('message').textContent=e.message}}
function insightNumbers(c){const n=c.numbers;if(c.kind==='spending_change')return 'Чистые расходы: '+n.previous+' → '+n.current+'; изменение '+n.change+'\nВ день: '+n.previous_daily+' → '+n.current_daily+'; изменение '+n.daily_change+'\nИзменение темпа, %: '+(n.relative_daily_change_percent??'не определено: прежняя база не положительна')+'\nНаблюдений: '+n.previous_observations+' → '+n.current_observations+'; дней: '+n.previous_days+' → '+n.current_days;if(c.kind==='recurring_candidate')return 'Наблюдений: '+n.observations+'; типичный чистый расход: '+n.typical_net_expense+'\nИнтервалы: '+n.gap_min_days+'–'+n.gap_max_days+' дней; следующая дата по последнему повторению: '+n.next_expected_date+' (гипотеза)\nОперации: '+n.transaction_ids.join(', ');return 'Чистый расход: '+n.amount+'; прежняя медиана: '+n.baseline_median+'\nОпераций в базе: '+n.baseline_observations+'; отношение к медиане: '+n.ratio+'; операция: '+n.transaction_id;}

$('insights-refresh').onclick=async()=>{try{const d=await api('/api/insights');const host=$('insights-data');host.replaceChildren();if(!d.cards?.length){const message=document.createElement('p');message.textContent=d.analysis_status==='available'?'По выбранным порогам значимых сигналов не найдено; это не оценка всех рисков.':'Пока недостаточно подтверждённых финансовых данных для анализа';host.append(message)}for(const n of d.notices||[]){const text=document.createElement('p');text.textContent=n.explanation+' ['+n.reason_code+']';host.append(text)}for(const c of d.cards||[]){const article=document.createElement('article');const title=document.createElement('h3');title.textContent=c.headline;const text=document.createElement('pre');text.textContent=c.explanation+'\n'+insightNumbers(c)+'\nИсточник: '+c.binding.source_sha256+'; audit revision: '+c.binding.audit_revision+'\nПериоды: '+c.binding.comparison_period.join(' — ')+' / '+c.binding.period.join(' — ')+'; валюта: '+c.binding.currency+'; '+(c.evidence==='low_observation_count'?'мало наблюдений':'принятая история')+'; '+(c.decision?.action||'current');article.append(title,text);for(const [action,label] of [['acknowledge','Ознакомлен'],['dismiss','Скрыть'],['reopen','Вернуть']]){const button=document.createElement('button');button.textContent=label;button.onclick=async()=>{await api('/api/insights/decision','POST',{task_id:c.task_id,card_id:c.id,action});$('insights-refresh').click()};article.append(button)}const review=document.createElement('button');review.textContent='Проверить категорию и источник';review.onclick=()=>{$('status').value='pending_review';offset=0;load();navigate('operations')};article.append(review);if(c.decision?.action==='dismiss'){text.hidden=true;title.textContent+=' [скрыто, audit сохранён]'}host.append(article)}}catch(e){$('insights-data').textContent=e.message}};
$('insights-scan').onclick=async()=>{try{await api('/api/insights/scan','POST',{month:$('question-month').value,currency:$('question-currency').value});$('insights-refresh').click();$('agent-tasks').click()}catch(e){$('insights-data').textContent=e.message}};
$('labels-progress').onclick=async()=>{try{const d=await api('/api/labels/progress');$('labels-progress-data').textContent='Подтверждено человеком: '+d.human_confirmed+'; требуют категории: '+d.pending_categories+'; конфликтов меток: '+d.conflicting_label_contexts+'; конфликтов источника: '+d.source_conflicts+'\nПредложения правил и моделей не являются метками. Подтверждение не принимает финансовый источник.';const host=$('labels-shortlist');host.replaceChildren();for(const id of d.review_ids){const button=document.createElement('button');button.textContent='Операция '+(d.review_ids.indexOf(id)+1)+' · выбрать категорию';button.onclick=()=>show(id);host.append(button)}}catch(e){$('labels-progress-data').textContent=e.message}};

$('agent-tasks').onclick=async()=>{try{const data=await api('/api/agent/tasks');const host=$('agent-results');host.replaceChildren();if(!Array.isArray(data.tasks)){host.textContent=data.reason;return}for(const task of data.tasks){const row=document.createElement('div');const text=document.createElement('pre');text.textContent=JSON.stringify(task,null,2);row.append(text);const cancel=document.createElement('button');cancel.textContent='Отменить задачу';cancel.onclick=async()=>{await api('/api/agent/tasks/'+task.task_id+'/cancel',{});$('agent-tasks').click()};row.append(cancel);const proposals=task.data?.result?.findings?.classify_pending?.suggestions||[];for(const proposal of proposals){const open=document.createElement('button');open.textContent='Проверить операцию';open.onclick=()=>show(proposal.item_id);row.append(open)}host.append(row)}}catch(e){$('message').textContent=e.message}};
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(!selected)return;try{
const cid=$('candidate').value;await api('/api/items/'+selected.id+'/decision',{action:b.dataset.action,actor:$('actor').value,
reason:$('why').value,expected_revision:selected.revision,candidate_id:b.dataset.action==='confirm_existing'&&cid?Number(cid):null});
await show(selected.id);await load();$('message').textContent='Решение сохранено только в review workspace.'}catch(e){$('message').textContent=e.message}});
$('refresh').onclick=()=>{offset=0;load()};$('next').onclick=()=>{offset+=50;load()};
$('previous').onclick=()=>{offset=Math.max(0,offset-50);load()};
for(const id of ['reason','classification','status'])$(id).onchange=()=>{offset=0;load()};
$('history').onclick=async()=>{try{$('evidence').textContent=JSON.stringify(await api('/api/audit'),null,2)}catch(e){$('message').textContent=e.message}};
$('report').onclick=async()=>{try{const d=await api('/api/report');const lines=['Покрытие: '+d.status,
'Активы: только подтверждённые банковские наблюдения; полный итог неизвестен.'];
for(const b of d.assets.known_bank_closing_subtotals)lines.push(b.asof+' · '+b.currency+' · '+b.amount+' (частичный итог)');
for(const p of d.statements){const m=p.metadata,r=p.reconciliation;lines.push((m.card||'Накопительный')+' · '+m.period.join('…')+
' · '+r.operation_count+' операций; '+r.opening+' → '+r.closing+' '+m.currency+'; Δ проверки '+r.discrepancy+'; источник '+p.source.sha256.slice(0,12))}
lines.push('Legacy ledger: '+d.legacy_ledger.status,'Бюджет/экономические категории: '+d.budget.status,
'Переводы: '+d.transfers.status,'Обязательства: '+d.liabilities.status,'Прогноз: '+d.forecast.status,
'Pending review: '+d.review.pending,...d.warnings);
for(const a of d.account_register)lines.push(a.alias+' · '+a.status+' · остаток: '+(a.verified_closing??'неизвестен')+' '+(a.currency??'')+
' · источник '+a.source_sha256.slice(0,12));
for(const e of d.source_errors)lines.push('Источник '+e.source_sha256.slice(0,12)+': '+e.status+' · '+e.reason);
downloadJson(d,'private-financial-source-report.json');$('product').textContent=lines.join('\n')}catch(e){$('message').textContent=e.message}};
$('labels').onclick=async()=>{try{const d=await api('/api/labels/export');$('product').textContent='ML: '+d.status+'; human labels: '+(d.human_labels||0)+
'; train: '+(d.train_size||0)+'; holdout: '+(d.test_size||0)+'\n'+(d.reason||'Обучение здесь не выполняется.');
downloadJson(d,'confirmed-review-labels.json')}catch(e){$('message').textContent=e.message}};
$('export').onclick=async()=>{try{const d=await api('/api/export');downloadJson(d,'private-review-packet.json');
$('message').textContent='Приватный packet сохранён: '+d.payload.items.length+' событий. Рабочая БД не менялась.'}catch(e){$('message').textContent=e.message}};
$('availability').onclick=async()=>{try{const d=await api('/api/availability');const lines=[d.note,'checked_at: '+d.checked_at,
'freshness policy: '+d.freshness_window_seconds+' seconds (не SLA банка)','database_modified: '+d.database_modified];
for(const [name,s] of Object.entries(d.sources))lines.push(name+' · '+s.status+'\nlast_success: '+(s.last_success??'неизвестно')+
'; last_attempt: '+(s.last_attempt??'неизвестно')+'\ncoverage: '+(s.coverage===null?'неизвестно':JSON.stringify(s.coverage))+
'\nmode: '+(s.mode??'local evidence check')+'; freshness basis: '+(s.freshness_basis??'см. timestamps/coverage')+
'; observed artifact time: '+(s.observed_artifact_time??'неизвестно')+
'\nsource_error: '+(s.source_error??'нет зафиксированной ошибки'));$('product').textContent=lines.join('\n\n')}catch(e){$('message').textContent=e.message}};
$('download-availability').onclick=async()=>{try{downloadJson(await api('/api/availability'),'private-availability-evidence.json')}
catch(e){$('message').textContent=e.message}};
$('provenance').onclick=async()=>{try{const d=await api('/api/provenance');downloadJson(d,'private-provenance-matrix.json');
$('product').textContent=d.status+' · '+d.reason+'\n'+d.matrix.length+' событий; financial_accepted: '+d.financial_accepted}catch(e){$('message').textContent=e.message}};
$('group-review').onclick=async()=>{if(!selected)return;try{const d=await api('/api/items/'+selected.id+'/group');
if(!d.eligible)throw Error('Нет одинаковой доказанной группы; проверяйте событие отдельно.');
const cid=$('candidate').value;const action=cid?'confirm_existing':'reject';
if(!confirm('Явно подтвердить '+d.items+' событий с одинаковыми докниколайельствами? Действие: '+action+'; group hash: '+d.group_hash))return;
await api('/api/items/'+selected.id+'/group',{group_hash:d.group_hash,action,actor:$('actor').value,reason:$('why').value,
confirmed:true,candidate_id:cid?Number(cid):null});await show(selected.id);await load()}catch(e){$('message').textContent=e.message}};
$('source').onclick=async()=>{if(!selected)return;const w=window.open('about:blank');try{const r=await fetch('/api/sources/'+selected.source_sha256,
{headers:{'X-Review-Token':token}});if(!r.ok)throw Error('Подтверждённый источник недоступен');const url=URL.createObjectURL(await r.blob());if(w)w.location.href=url;
setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){if(w)w.close();$('message').textContent=e.message}};
document.querySelectorAll('[data-label]').forEach(b=>b.onclick=async()=>{if(!selected||labelBusy)return;labelBusy=true;document.querySelectorAll('[data-label]').forEach(x=>x.disabled=true);try{const actor=$('actor').value.trim();if(!actor)throw Error('Укажите, кто подтверждает категорию; имя запомнится в этом браузере');const reason=$('why').value.trim();if(!reason)throw Error('Выберите основание или напишите комментарий');await api('/api/items/'+selected.id+'/label',{
action:b.dataset.label,actor,reason,expected_revision:selected.label_revision||0,category:b.dataset.label==='confirm'?$('category').value:null});localStorage.setItem('jarvis-review-actor',actor);$('message').textContent='Категория сохранена. Финансовые данные не изменены.';await load();await updateOverview();if(b.dataset.label==='confirm'){await nextOperation(selected.id)}else{await show(selected.id)}}catch(e){$('message').textContent=e.message}finally{labelBusy=false;document.querySelectorAll('[data-label]').forEach(x=>x.disabled=false)}});
$('sber-status').onclick=async()=>{try{const d=await api('/api/sber-connection');const box=$('sber-status-data');box.replaceChildren();
for(const text of ['Настоящий банк: подключение заблокировано',
'Локальный DPAPI codec: '+(d.storage_status==='available'?'доступен':'недоступен'),
'Совместимость SDK: только disposable fixtures; настоящий профиль не проверен',
'Остатки и покрытие: неизвестны; данные не подменяются нулями',...(d.blockers||[])]){
const p=document.createElement('p');p.textContent=text;box.appendChild(p)}}catch(e){$('message').textContent=e.message}};
api('/api/labels/policy').then(d=>{for(const c of (d.categories||[]))$('category').add(new Option(categoryName(c),c))}).catch(e=>$('message').textContent=e.message);
api('/api/groups').then(d=>{for(const g of d.reasons)$('reason').add(new Option(g,g));load()}).catch(e=>$('message').textContent=e.message);

let labelBusy=false,shortlist=[],returnFocus=null;
const titles={home:'Главная',operations:'Операции',learning:'Обучение Jarvis',analytics:'Аналитика',assistant:'AI-ассистент',research:'Интернет-исследования',sources:'Сбербанк и источники',tasks:'Задачи',settings:'Настройки'};
function navigate(view){if(!titles[view])view='home';document.querySelectorAll('[data-view]').forEach(x=>x.hidden=x.dataset.view!==view);document.querySelectorAll('[data-nav]').forEach(x=>{if(x.dataset.nav===view)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});$('page-title').textContent=titles[view];history.replaceState(null,'','#'+view);$('page-title').focus();if(view==='learning')$('labels-progress').click();if(view==='analytics')$('statement-history').click();if(view==='tasks')$('agent-tasks').click()}
function categoryName(value){return ({food:'Продукты',food_basic:'Продукты',transport:'Транспорт',salary:'Зарплата',stipend:'Стипендия',subscriptions:'Подписки',entertainment:'Развлечения',health:'Здоровье',shopping:'Покупки',refund:'Возврат',own_transfer:'Перевод между своими счетами'})[value]||value||'Не выбрана'}
function moneyText(amount,currency){if(amount===null||amount===undefined)return 'Сумма неизвестна';const m=String(amount).match(/^(-?)([0-9]+)(?:\.([0-9]+))?$/);if(!m)return 'Сумма требует проверки';return (m[1]?'−':'')+m[2].replace(/\B(?=(\d{3})+(?!\d))/g,' ')+(m[3]?','+m[3]:'')+' '+(currency||'валюта неизвестна')}
function renderOperation(item){$('teacher-preview-data').textContent='';$('teacher-send-confirm').checked=false;$('teacher-result').textContent='';$('category-assist-state').textContent='';returnFocus=document.activeElement;$('detail-title').textContent=item.operation.merchant||item.operation.description||'Операция без описания';$('operation-summary').textContent=moneyText(item.operation.amount,item.operation.currency)+' · '+(item.operation.tx_date||'Дата неизвестна')+' · '+(item.statement_card?'••'+item.statement_card.slice(-4):'Счёт скрыт');const p=item.category_suggestion;const names={human_feedback:'Ваши прежние подтверждения',merchant_rule:'Локальное правило',conflicting_human_feedback:'Ваши подтверждения противоречат друг другу',no_match:'Недостаточно оснований',source_conflict:'Конфликт источников'};$('suggestion-summary').textContent=p?.suggested_category?'Предложение: '+categoryName(p.suggested_category)+' · '+(names[p.reason_code]||'Локальный механизм')+'. Это ещё не подтверждённая категория.':names[p?.reason_code]||'Категория пока не определена';const confirmed=item.label_decision?.action==='confirm'?item.label_decision.category:null;const candidate=confirmed||p?.suggested_category;if(candidate&&Array.from($('category').options).some(x=>x.value===candidate))$('category').value=candidate;else $('category').value='';$('actor').value=localStorage.getItem('jarvis-review-actor')||$('actor').value;$('quick-reason').selectedIndex=0;$('why').value=$('quick-reason').value;$('category').focus()}
function closeDetail(){$('detail').hidden=true;if(returnFocus?.isConnected)returnFocus.focus()}
$('detail-close').onclick=closeDetail;
$('quick-reason').onchange=()=>{$('why').value=$('quick-reason').value};
$('skip-operation').onclick=()=>{if(selected&&!labelBusy)nextOperation(selected.id)};
async function nextOperation(id){const d=await api('/api/labels/progress');const at=d.review_ids.indexOf(id);shortlist=at<0?d.review_ids:d.review_ids.slice(at+1);if(shortlist.length)await show(shortlist[0]);else{closeDetail();$('message').textContent='В этой подборке больше нет операций для категории. Проверьте очередь и конфликты.'}}
async function updateOverview(){try{const d=await api('/api/labels/progress');$('home-pending').textContent=d.pending_categories;$('home-labels').textContent=d.human_confirmed;shortlist=d.review_ids;$('home-state').textContent=d.policy_configured?'Подтверждения помогают локальным предложениям. Финансовый импорт выключен.':'Для подтверждения категорий требуется настроенная политика разметки.'}catch(e){$('home-pending').textContent='Недоступно';$('home-labels').textContent='Недоступно';$('home-state').textContent=e.message}}
$('start-learning').onclick=()=>navigate('learning');
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
document.addEventListener('keydown',e=>{if($('detail').hidden)return;if(e.key==='Escape')closeDetail();if(e.key==='Tab'){const nodes=Array.from($('detail').querySelectorAll('button,input,select,textarea,summary')).filter(n=>!n.disabled&&n.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function setTheme(theme){document.documentElement.dataset.theme=theme;$('theme-toggle').textContent=theme==='dark'?'Светлая тема':'Тёмная тема';localStorage.setItem('jarvis-theme',theme)}
$('theme-toggle').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');setTheme(localStorage.getItem('jarvis-theme')==='light'?'light':'dark');
navigate(location.hash.slice(1));updateOverview();

function scenarioExplanation(data){if(data.scope==='HYPOTHETICAL'&&data.tool){const names={future_amount:'Итоговая сумма',monthly_payment:'Платёж в месяц',total_payment:'Теоретическая сумма платежей',interest:'Теоретические проценты',purchasing_power:'В ценах начала периода'};return ['Гипотетический расчёт; реальные деньги не изменены.',...Object.entries(data.output||{}).map(([k,v])=>(names[k]||k)+': '+moneyText(v,data.currency)),'Сумма: '+moneyText(data.principal,data.currency)+'; годовая ставка / инфляция: '+data.annual_rate_percent+'%; месяцев: '+data.months,'Формула: '+data.formula,data.explanation,'Комиссии и реальные тарифы неизвестны. Источник: введённые вами параметры, не принятые банковские данные.'].join('\n')}if(data.scope==='HYPOTHETICAL'){return ['Гипотетический расчёт; настоящие деньги и цели не меняются.','Цель: '+moneyText(data.target,data.currency),'Начальная сумма: '+moneyText(data.starting,data.currency),'Взнос: '+moneyText(data.monthly_contribution,data.currency)+' в месяц','Итог к концу горизонта: '+moneyText(data.projected_amount,data.currency),'Для указанного срока нужно в месяц: '+(data.required_monthly===null?'Укажите срок цели':moneyText(data.required_monthly,data.currency)),'Цель в пределах горизонта: '+(data.reachable_in_horizon===null?'взнос не задан; достижимость неизвестна':data.reachable_in_horizon?'достижима при заданных взносах':'не достигается при заданных взносах'),'Дата достижения: '+(data.goal_date||'не определена в этом горизонте'),'Формула: '+data.formula+'. Без процентов, инфляции и обмена валют.','Источник: только введённые вами гипотетические параметры.'].join('\n')}
if(data.scenarios){const lines=['Расчёт по отдельно принятым источникам; будущий доход неизвестен.'];for(const [name,result] of Object.entries(data.scenarios))lines.push(name+': свободный остаток '+moneyText(result.headroom,data.input_summary?.currency)+'; дефицит '+moneyText(result.shortfall,data.input_summary?.currency));return lines.join('\n')}
return 'Расчёт недоступен: недостаточно явных параметров или принятых данных. Автоматический финансовый apply запрещён.'}
$('category-assist').onclick=async()=>{if(!selected)return;const id=selected.id;const button=$('category-assist');button.disabled=true;try{const suggestion=await api('/api/items/'+id+'/category-suggestion');if(selected?.id!==id)return;selected.category_suggestion=suggestion;renderOperation(selected);$('category-assist-state').textContent='Локальное предложение обновлено. Платных вызовов нет. Qwen teacher для приватных операций ещё не настроен; данные не отправлены в облако.'}catch(e){$('category-assist-state').textContent=e.message}finally{button.disabled=false}};

let teacherMode=null,teacherPreview=null,teacherBusy=false;
$('teacher-actor').value=localStorage.getItem('jarvis-review-actor')||'';
$('teacher-refresh').onclick=async()=>{try{const d=await api('/api/teacher/status');teacherMode=d.mode==='mock'?'mock':'live';const host=$('teacher-permissions');host.replaceChildren();$('teacher-policy-state').textContent='Режим: '+(d.mode==='mock'?'MOCK — симуляция':d.mode==='cloud_opt_in'?'облако отдельно разрешено':'облако выключено')+'. '+(d.configured?'Журнал и каталог настроены; это не проверка транспорта.':'Нужны существующий RUB journal и свежий каталог цен.');for(const g of d.permissions){const row=document.createElement('article');const text=document.createElement('p');text.textContent=(g.status==='active'?'Действует':'Недоступно / отозвано / истекло')+' · '+g.policy.mode+' · поля '+g.policy.fields.join(', ')+' · срок '+g.policy.expires_at+' · до '+g.policy.maximum_requests+' операций';row.append(text);const choose=document.createElement('button');choose.textContent='Использовать это разрешение';choose.disabled=g.status!=='active';choose.onclick=()=>{localStorage.setItem('jarvis-teacher-permission',g.permission_id);$('teacher-policy-state').textContent='Выбрано разрешение. Проверьте поля в карточке операции перед запросом.'};const revoke=document.createElement('button');revoke.textContent='Отозвать';revoke.onclick=async()=>{try{await api('/api/teacher/revoke',{permission_id:g.permission_id,actor:$('teacher-actor').value});if(localStorage.getItem('jarvis-teacher-permission')===g.permission_id)localStorage.removeItem('jarvis-teacher-permission');teacherPreview=null;$('teacher-refresh').click()}catch(e){$('teacher-policy-state').textContent=e.message}};row.append(choose,revoke);host.append(row)}}catch(e){$('teacher-policy-state').textContent=e.message}};
$('teacher-grant').onclick=async()=>{try{if(!$('teacher-grant-confirm').checked)throw Error('Требуется отдельное явное разрешение владельца');if(!teacherMode)throw Error('Сначала проверьте разрешения и режим');const fields=[];if($('teacher-merchant').checked)fields.push('merchant');if($('teacher-description').checked)fields.push('description');if(!fields.length)throw Error('Выберите допустимые поля');const policy={mode:teacherMode,fields,expires_at:new Date(Date.now()+Number($('teacher-hours').value)*3600000).toISOString(),maximum_requests:Number($('teacher-max').value),request_budget_rub:'0.03',daily_budget_rub:$('teacher-day').value,monthly_budget_rub:$('teacher-month').value};const d=await api('/api/teacher/grant',{policy,actor:$('teacher-actor').value,confirmed:true});localStorage.setItem('jarvis-review-actor',$('teacher-actor').value);localStorage.setItem('jarvis-teacher-permission',d.permission_id);$('teacher-grant-confirm').checked=false;$('teacher-refresh').click()}catch(e){$('teacher-policy-state').textContent=e.message}};
$('teacher-preview').onclick=async()=>{teacherPreview=null;$('teacher-send-confirm').checked=false;try{if(!selected)throw Error('Выберите операцию');const permission_id=localStorage.getItem('jarvis-teacher-permission');if(!permission_id)throw Error('Сначала сохраните отдельное разрешение в Настройках');const id=selected.id;const d=await api('/api/items/'+id+'/teacher-preview',{permission_id});if(selected?.id!==id)return;teacherPreview={id,permission_id,binding:d.binding};$('teacher-preview-data').textContent=Object.entries(d.fields).map(([field,value])=>field+': '+value).join('\n')+'\nМаксимум 400 output tokens; потолок '+d.request_budget_rub+' RUB. Тариф и остаток бюджета повторно проверяются перед отправкой.'}catch(e){$('teacher-preview-data').textContent=e.message}};
function teacherOutcome(d){const code=d.reason_code||(d.basis==='insufficient_data'?'insufficient_data':d.cached?'already_recorded':'unclassified_outcome');const messages={insufficient_data:'Qwen воздержался: недостаточно оснований для категории.',invalid_json:'Ответ не является корректным JSON.',invalid_schema:'JSON не соответствует схеме категории.',unknown_category:'Категория отсутствует в разрешённой политике.',inconsistent_basis:'Категория и основание ответа противоречат друг другу.',source_or_permission_changed:'Источник или разрешение изменились.',empty_completion:'Модель не вернула полный итоговый ответ.',output_truncated:'Ответ обрезан лимитом токенов.',unexpected_tool_calls:'Модель вернула запрещённый вызов инструмента.',invalid_content_type:'Неподдерживаемый тип итогового ответа.',invalid_finish_reason:'Неожиданное завершение ответа модели.',billing_exceeded:'Списание превысило резерв; ответ не принят.',unknown_debit:'Списание неизвестно; резерв сохранён.',recorded_unknown:'Сохранён прежний UNKNOWN; повторной отправки нет.',already_recorded:'Запрос уже записан; новое предложение не запрашивалось.',permission_revoked:'Разрешение отозвано до публикации.',unclassified_outcome:'Причина не сохранена; вывод по догадке невозможен.'};return (messages[code]||'Ответ не прошёл проверку.')+' Код: '+code+'. Автоматического повтора нет. ';}
$('teacher-send').onclick=async()=>{if(teacherBusy)return;teacherBusy=true;$('teacher-send').disabled=true;try{if(!selected||!teacherPreview||teacherPreview.id!==selected.id||teacherPreview.permission_id!==localStorage.getItem('jarvis-teacher-permission')||!$('teacher-send-confirm').checked)throw Error('Покажите поля и подтвердите один запрос');const approved=teacherPreview;const fresh=await api('/api/items/'+approved.id+'/teacher-preview',{permission_id:approved.permission_id});if(fresh.binding!==approved.binding)throw Error('Источник изменился; проверьте поля заново');const d=await api('/api/items/'+approved.id+'/teacher',{permission_id:approved.permission_id,expected_binding:approved.binding});if(selected?.id!==approved.id)return;const good=d.status==='suggestion'&&d.category&&Array.from($('category').options).some(x=>x.value===d.category);$('teacher-result').textContent=(d.simulation?'MOCK, не настоящий ответ Qwen. ':'')+(good?'Предложение: '+categoryName(d.category)+'. Оно не подтверждено владельцем. ':teacherOutcome(d))+'Стоимость нового запроса: '+(d.cost_rub??'неизвестна')+' RUB; резерв: '+(d.reserved_rub??'неизвестен')+' RUB; '+(d.original_cost_rub?'историческое списание '+d.original_cost_rub+' RUB; ':'')+(d.simulation?'симулировано':'реальный учёт');if(good)$('category').value=d.category}catch(e){$('teacher-result').textContent=e.message}finally{teacherBusy=false;teacherPreview=null;$('teacher-send-confirm').checked=false;$('teacher-send').disabled=false}};

$('calc-run').onclick=async()=>{const button=$('calc-run');if(button.disabled)return;button.disabled=true;try{const scenario={mode:$('calc-mode').value,principal:$('calc-principal').value,annual_rate_percent:$('calc-rate').value,months:Number($('calc-months').value),start:$('calc-start').value,currency:$('calc-currency').value};const message='Гипотетический финансовый расчёт';const answer=await api('/api/chat',{message,conversation_id:conversationId,request_id:crypto.randomUUID().replaceAll('-',''),public_cloud:false,scenario});renderChat(message,answer);navigate('assistant');$('calc-state').textContent='Результат в ассистенте; финансовых действий нет.'}catch(e){$('calc-state').textContent=e.message}finally{button.disabled=false}};

let webPermission=localStorage.getItem('jarvis-public-research-permission')||'';
let webRequest=webPermission?localStorage.getItem('jarvis-public-research-request:'+webPermission):null;
function webReport(result){const row=document.createElement('article');const heading=document.createElement('h3');heading.textContent='Исследование '+(result.task_id||'')+': '+(result.state||result.status||'недоступно');row.append(heading);
const findings=result.data?.result?.findings;if(findings?.public_candidates?.synthetic)heading.textContent='DEMO / MOCK — '+heading.textContent;const explanation=findings?.explain_public_sources;const note=document.createElement('p');note.textContent=result.reason||result.data?.reason||'Извлечённые цитаты; свободный синтез и категория не подтверждены. Противоречия требуют сравнения источников.';row.append(note);
for(const citation of (explanation?.citations||[])){const quote=document.createElement('blockquote');quote.textContent=citation.quote;const link=document.createElement('a');link.textContent=citation.url;if(/^https:\/\//.test(citation.url)){link.href=citation.url;link.target='_blank';link.rel='noopener noreferrer'}row.append(quote,link);const metadata=document.createElement('small');const source=findings?.read_public_sources?.sources?.find(s=>s.doc_id===citation.doc_id);metadata.textContent=' SHA-256: '+citation.source_sha256+'; получено: '+(source?.observed_at||'неизвестно')+'; опубликовано: '+(source?.published_at||'неизвестно, дата не выдумывается');row.append(metadata)}
const costs=document.createElement('p');costs.textContent='Платная LLM и платный search API не вызывались. Условия самого SearXNG instance определяет его оператор. Финансового apply нет.';row.append(costs);$('web-reports').append(row)}
$('web-status').onclick=async()=>{try{const d=await api('/api/research/status');$('web-state').textContent=(d.mode==='mock'?'DEMO / MOCK: не настоящий интернет. ':'')+d.status+'; '+(d.journal_configured?'приватный журнал настроен':'нужен --agent-journal')+'. Нужен JSON-enabled SearXNG, публичная тема, домены и отдельное разрешение.'}catch(e){$('web-state').textContent=e.message}};
$('web-grant').onclick=async()=>{try{if(!$('web-consent').checked)throw Error('Сначала подтвердите публичный scope и условия бесплатного HTTP');const status=await api('/api/research/status');const hours=Number($('web-hours').value);if(!Number.isInteger(hours)||hours<1||hours>24)throw Error('Срок: от 1 до 24 часов');const d=await api('/api/research/grant',{public_only_confirmed:true,policy:{mode:status.mode,topics:[$('web-topic').value.trim()],urls:[],domains:$('web-domains').value.split(',').map(s=>s.trim()).filter(Boolean),search_endpoint:$('web-endpoint').value.trim(),expires_at:new Date(Date.now()+hours*3600000).toISOString(),free_http:true,paid_llm:false,paid_search:false,maximum_tasks:1,maximum_steps:4,maximum_network_requests:9,maximum_model_calls:0}});webPermission=d.policy_id;webRequest=null;localStorage.setItem('jarvis-public-research-permission',webPermission);$('web-state').textContent='Разрешение сохранено. Сетевых запросов ещё не было.'}catch(e){$('web-state').textContent=e.message}};
$('web-run').onclick=async()=>{const b=$('web-run');if(b.disabled)return;b.disabled=true;try{if(!webPermission)throw Error('Сначала настройте и разрешите одну публичную тему');const scope=await api('/api/research/'+webPermission+'/scope');if(($('web-topic').value.trim()&&$('web-topic').value.trim()!==scope.topic)||($('web-endpoint').value.trim()&&$('web-endpoint').value.trim()!==scope.search_endpoint)||($('web-domains').value.trim()&&JSON.stringify($('web-domains').value.split(',').map(v=>v.trim()).filter(Boolean).sort())!==JSON.stringify([...scope.domains].sort())))throw Error('Параметры изменены: нужно новое разрешение на публичную тему');$('web-topic').value=scope.topic;$('web-endpoint').value=scope.search_endpoint;$('web-domains').value=scope.domains.join(', ');webRequest=webRequest||crypto.randomUUID().replaceAll('-','');localStorage.setItem('jarvis-public-research-request:'+webPermission,webRequest);$('web-state').textContent='Получаю разрешённые публичные источники…';const d=await api('/api/research/run',{policy_id:webPermission,request_id:webRequest});webReport(d);$('web-state').textContent=d.state==='COMPLETED'?'Отчёт с цитатами сохранён в задачах.':'Достоверный отчёт не получен: '+d.state}catch(e){$('web-state').textContent=e.message}finally{b.disabled=false}};
$('web-revoke').onclick=async()=>{try{if(!webPermission)throw Error('Нет выбранного разрешения');await api('/api/research/'+webPermission+'/revoke','POST',{});localStorage.removeItem('jarvis-public-research-permission');webPermission='';webRequest=null;$('web-reports').replaceChildren();$('web-state').textContent='Разрешение отозвано; прежние отчёты не считаются актуальными.'}catch(e){$('web-state').textContent=e.message}};
$('web-tasks').onclick=async()=>{try{const d=await api('/api/research/tasks');$('web-reports').replaceChildren();for(const t of d.tasks||[])webReport(t);$('web-state').textContent=d.tasks?.length?'Сохранённые задачи; свежесть проверена локально.':'Сохранённых исследований нет. '+d.status}catch(e){$('web-state').textContent=e.message}};
const tgFields=()=>['merchant','description','amount','date','card'].filter(k=>$('tg-'+k).checked);let tgPreview=null;
$('tg-save-token').onclick=async()=>{try{const value=$('tg-token').value;$('tg-token').value='';await api('/api/telegram/token',{token:value});$('tg-state').textContent='Токен зашифрован. Старые разрешения отозваны. Запустите polling отдельно.'}catch(e){$('tg-state').textContent=e.message}};
$('tg-preview').onclick=async()=>{try{tgPreview=await api('/api/telegram/preview',{fields:tgFields(),finance_reports:$('tg-finance').checked});$('tg-preview-data').textContent=JSON.stringify({operations:tgPreview.operations.map(o=>o.visible),report_fields:tgPreview.report_fields},null,2);$('tg-consent').checked=false}catch(e){$('tg-state').textContent=e.message}};
$('tg-pair').onclick=async()=>{try{if(!tgPreview||!$('tg-consent').checked||JSON.stringify(tgPreview.fields)!==JSON.stringify(tgFields())||tgPreview.finance_reports!==$('tg-finance').checked)throw Error('Сначала проверьте точные поля и подтвердите согласие');const d=await api('/api/telegram/pair',{code:$('tg-code').value,fields:tgFields(),expected_preview:tgPreview.binding,confirmed:true,finance_reports:$('tg-finance').checked});$('tg-code').value='';tgPreview=null;$('tg-consent').checked=false;$('tg-state').textContent=d.enabled?'Привязка завершена. /review использует общую очередь сайта.':'Привязка не разрешена'}catch(e){$('tg-state').textContent=e.message}};
$('tg-status').onclick=async()=>{try{const d=await api('/api/telegram/status');$('tg-state').textContent=(d.enabled?'Включён':'Выключен')+'; токен: '+(d.token_present?'файл сохранён, проверяется при запуске':'не задан')+'; поля: '+d.fields.join(', ')+(d.synthetic?'; MOCK, не настоящий Telegram':'')}catch(e){$('tg-state').textContent=e.message}};
$('tg-disable').onclick=async()=>{try{await api('/api/telegram/disable',{});$('tg-state').textContent='Отключён. Старые кнопки недействительны, решения сохранены.'}catch(e){$('tg-state').textContent=e.message}};

async function loadStatements(){try{const d=await api('/api/statements');$('statement-list').replaceChildren();for(const s of d.sources){const row=document.createElement('article');row.className='operation';const title=document.createElement('h3');title.textContent=(s.accepted?'Принят источник':'Ожидает принятия')+' · ••'+String(s.metadata.local_account).slice(-4);const details=document.createElement('p');details.textContent='Банковский счёт '+s.metadata.bank_account+' → local '+s.metadata.local_account+' · '+s.metadata.period.join(' — ')+' · '+s.metadata.currency+' · операций '+s.operation_count+' · opening '+s.metadata.opening+' → closing '+s.metadata.closing+' · SHA-256 '+s.sha256;const consent=document.createElement('input');consent.type='checkbox';const label=document.createElement('label');label.append(consent,document.createTextNode(s.accepted?' Подтверждаю отзыв источника и пересчёт отчётов':' Я проверил счёт, период, остатки и оригинал; принимаю источник. Категории проверяются отдельно.'));const warningConsent=document.createElement('input');warningConsent.type='checkbox';if(s.parser_warnings?.length){const warning=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Предупреждения парсера: '+s.parser_warnings.length+' — требуют просмотра';warning.append(summary);for(const value of s.parser_warnings){const p=document.createElement('p');p.textContent=value;warning.append(p)}const warningLabel=document.createElement('label');warningLabel.append(warningConsent,document.createTextNode(' Я сверил предупреждения с оригиналом; они не скрывают пропущенные операции.'));row.append(warning,warningLabel)}const button=document.createElement('button');button.textContent=s.accepted?'Отозвать источник':'Принять источник';button.onclick=async()=>{if(!consent.checked){$('statement-state').textContent='Нужно явное подтверждение источника';return}button.disabled=true;try{await api('/api/statements/'+s.id+'/decision',{actor:'local-owner',expected_revision:s.revision,accept:!s.accepted,confirmed:true,acknowledge_parser_warnings:warningConsent.checked});$('statement-state').textContent='Решение сохранено в audit. Рабочая БД не изменена. '+(s.accepted?'Источник отозван.':'Разберите категории в операциях.');await loadStatements()}catch(e){$('statement-state').textContent=e.message}finally{button.disabled=false}};const original=document.createElement('button');original.textContent='Открыть проверенный оригинал';original.onclick=async()=>{try{const r=await fetch('/api/statements/'+s.id+'/original',{headers:{'X-Review-Token':token}});if(!r.ok)throw Error('Оригинал недоступен или изменён');const url=URL.createObjectURL(await r.blob());const link=document.createElement('a');link.href=url;link.download='private-statement.'+s.format;link.click();URL.revokeObjectURL(url)}catch(e){$('statement-state').textContent=e.message}};const chat=document.createElement('button');chat.textContent='Спросить Jarvis по этому счёту';chat.disabled=!s.accepted||!/^\d{4}$/.test(String(s.metadata.card||s.metadata.bank_account).replace(/\D/g,'').slice(-4));chat.onclick=()=>{const card=String(s.metadata.card||'').replace(/\D/g,'').slice(-4);const alias=card?'карте ••'+card:'счёту ••'+String(s.metadata.bank_account).slice(-4);$('chat-month').value='';$('chat-input').value='Покажи движение денег по '+alias+' с '+s.metadata.period[0]+' по '+s.metadata.period[1];navigate('assistant');$('chat-input').focus()};const provenance=document.createElement('button');provenance.textContent='Происхождение исходных строк';provenance.disabled=s.format!=='pdf';provenance.onclick=async()=>{try{const p=await api('/api/statements/'+s.id+'/provenance');const box=document.createElement('pre');box.textContent='Read-only provenance '+p.version+'; неприкреплённых строк: '+p.unbound_count+'\n'+p.rows.map(r=>'#'+r.ordinal+' · стр. '+r.page+' · строка '+r.line+' · '+r.operation_date+' '+r.operation_time+' · обработка '+(r.processing_date||'неизвестно')+' · auth '+(r.authorization_code||'неизвестно')+'\nEvidence: '+r.evidence_id).join('\n');row.append(box)}catch(e){$('statement-state').textContent=e.message}};row.append(title,details,original,label,button,chat,provenance);$('statement-list').append(row)}if(!d.sources.length)$('statement-state').textContent='Выписки ещё не подготовлены. Загрузите оригинал.'}catch(e){$('statement-state').textContent=e.message}}
$('statement-refresh').onclick=loadStatements;
$('statement-upload').onclick=async()=>{const b=$('statement-upload');b.disabled=true;try{const f=$('statement-file').files[0];if(!f)throw Error('Выберите оригинал PDF/CSV');if(f.size>20*1024*1024)throw Error('Файл превышает 20 МБ');const form=new FormData();form.append('file',f);if($('statement-csv-scope').value.trim())form.append('csv_scope',$('statement-csv-scope').value);const r=await fetch('/api/statements/preview',{method:'POST',headers:{'X-Review-Token':token},body:form});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Не удалось проверить выписку');$('statement-state').textContent='Баланс сошёлся; операций '+d.operation_count+'. Источник ещё не принят. SHA-256 '+d.sha256;await loadStatements()}catch(e){$('statement-state').textContent=e.message}finally{b.disabled=false}};
