function autopilotAnswer(task){return task.answer||task.data?.result?.findings?.local_statement_analysis?.answer||task.data?.result?.findings?.analyze_accepted_aggregates?.answer;}
function showAutopilot(host,task){host.replaceChildren();const answer=autopilotAnswer(task);const text=document.createElement('pre');text.textContent=answer?.text||task.data?.reason||task.reason||'Данные для анализа недоступны';host.append(text);const note=document.createElement('p');note.textContent='Статус: '+task.state+'; '+(task.cached?'сохранённая задача, без нового вызова':'локальные источники проверены')+'; финансовый apply выключен.';host.append(note);if(answer?.source_revisions?.length){const proof=document.createElement('small');proof.textContent='Версия и хеш источника: '+answer.source_revisions.join(' / ');host.append(proof)}}
