$('qwen-readiness').onclick=async()=>{const b=$('qwen-autopilot');b.disabled=true;delete b.dataset.binding;try{const month=$('autopilot-month').value;const d=await api('/api/agent/qwen-readiness'+(/^\d{4}-\d{2}$/.test(month)?'?month='+encodeURIComponent(month):''));const c=d.ledger_capacity||{};const rows=[d.status+' · '+(d.reason||''),'Owner monthly: '+(d.owner_monthly_budget_rub??'UNKNOWN')+' RUB; configured monthly: '+(d.configured_monthly_budget_rub??'UNKNOWN')+' RUB','Остаток эффективного локального лимита (не деньги провайдера): месяц '+(c.remaining_month??'UNKNOWN')+'; день '+(c.remaining_day??'UNKNOWN'),'Известно списано: '+(c.settled_total??'UNKNOWN')+'; pending reserve: '+(c.open_reservations??'UNKNOWN')+'; UNKNOWN reserve: '+(c.unknown_reservations??'UNKNOWN'),'Лимит запроса: '+(d.request_ceiling_rub??'UNKNOWN')+'; максимальный резерв: '+(d.maximum_reserve_rub??'UNKNOWN')+' RUB','Тариф: '+(d.pricing?.status||'UNKNOWN')+'; наблюдался '+(d.pricing?.observed_at||'UNKNOWN'),'Модель: '+(d.model||'UNKNOWN')+'; провайдер/ограничения: '+d.provider_status+'; исполнение одного запроса: '+d.eligible_one_task,'Разрешено вызовов осталось: '+(d.remaining_invocations??'UNKNOWN')+'; срок: '+(d.expires_at||'UNKNOWN'),'Пилот в UI поддерживает RUB; другой currency scope здесь не включается. Передаются только metrics,coverage. Операции, merchants, счета и PDF остаются локальными.','HTTP: '+d.http_requests+'; новое разрешение не создавалось.'];if(d.source_scope)rows.push('Период: '+d.source_scope.period.join(' — ')+'; валюта: '+d.source_scope.currency,'Агрегаты preview: '+JSON.stringify(d.source_scope.aggregate_fields));$('autopilot-data').textContent=rows.join('\n');b.disabled=!(d.local_eligible&&d.mode==='live'&&d.source_scope?.currency==='RUB'&&!$('local-autopilot').disabled);b.dataset.ceiling=d.request_ceiling_rub||'';b.dataset.binding=d.preview_binding||''}catch(e){$('autopilot-data').textContent=e.message}};

$('qwen-autopilot').onclick=async()=>{const month=$('autopilot-month').value;const b=$('qwen-autopilot');const ceiling=b.dataset.ceiling;const preview_binding=b.dataset.binding;if(!/^\d{4}-\d{2}$/.test(month)||!ceiling||!preview_binding){$('autopilot-data').textContent='Выберите месяц и проверьте актуальный preview.';return}if(!confirm('Разрешить финансовый анализ Qwen в показанных пределах за '+month+'? Только агрегаты/coverage, до '+ceiling+' RUB. Провайдер ещё проверяется; возможен отказ. Без новых банковских/Telegram полномочий, retry и fallback.'))return;b.disabled=true;try{const result=await api('/api/agent/qwen-analysis','POST',{month,currency:'RUB',preview_binding,owner_confirmed:true});showAutopilot($('autopilot-data'),result);const status=document.createElement('p');status.textContent='Pilot: '+(result.pilot_status||'BLOCKED')+'; genuine result: '+(result.genuine_model_result?'YES':'NO');$('autopilot-data').append(status)}catch(e){$('autopilot-data').textContent=e.message}};

